INSERT INTO videojuego (titulo, descripcion, imagen_url) VALUES
('GTA VI', 'La ciudad de Vice City esconde una red de crimen organizado que crece sin control. Tu misión es desarrollar un juego de mundo abierto inspirado en el universo de GTA VI, donde los jugadores puedan explorar la ciudad libremente, completar misiones y vivir historias de acción y crimen.', 'https://colombiajuegosdigitales.com/wp-content/uploads/2026/06/Grand-Theft-Auto-VI-PS5.webp'),
('Uncharted 4', 'Un tesoro pirata legendario ha permanecido oculto durante siglos, esperando ser encontrado. Tu misión es desarrollar un juego de aventuras y acción inspirado en el universo de Uncharted, donde los jugadores puedan explorar ruinas antiguas, resolver acertijos y enfrentarse a peligrosos rivales en busca del tesoro.', 'https://juegosdigitalescolombia.com/files/images/thumbs/productos_300x400_1576686876-uncharted-4-el-desenlace-del-ladron-ps4.jpg'),
('Assassin''s Creed Black Flag', 'Los mares del Caribe están llenos de riquezas, piratas y secretos de la Orden de los Asesinos. Tu misión es desarrollar un juego de acción y navegación inspirado en el universo de Assassin''s Creed, donde los jugadores puedan comandar su propio barco, abordar naves enemigas y descubrir conspiraciones ocultas.', 'https://juegosdigitalescolombia.com/files/images/productos/1783626737-assassins-creed-black-flag-resynced-ps5-0.webp'),
('Fortnite', 'Cien jugadores caen sobre una isla y solo uno puede quedar en pie. Tu misión es desarrollar un juego de batalla real inspirado en el universo de Fortnite, donde los jugadores puedan construir estructuras, recolectar recursos y enfrentarse a otros participantes hasta ser el último sobreviviente.', 'https://m.media-amazon.com/images/I/917JLu3S8DL._AC_UF1000,1000_QL80_.jpg');